package com.alpharip.staffmod.BuildTimelapse.ui;
import com.alpharip.staffmod.BuildTimelapse.timeline.*;import net.minecraft.client.gui.GuiButton;import net.minecraft.client.gui.GuiScreen;import net.minecraft.client.gui.GuiTextField;
public final class TimelineEditorScreen extends GuiScreen {
 private final GuiScreen parent;private final Timeline timeline;private GuiTextField markerName,trackName;private String status="Timeline ready";
 public TimelineEditorScreen(GuiScreen p,Timeline t){if(p==null||t==null)throw new IllegalArgumentException();parent=p;timeline=t;}
 @Override public boolean doesGuiPauseGame(){return false;}
 @Override public void initGui(){buttonList.clear();markerName=new GuiTextField(0,fontRendererObj,width/2-150,height/2+48,140,20);markerName.setMaxStringLength(48);trackName=new GuiTextField(1,fontRendererObj,width/2+10,height/2+48,140,20);trackName.setMaxStringLength(48);int y=height/2+76;buttonList.add(new GuiButton(0,width/2-150,y,140,20,"Add Marker"));buttonList.add(new GuiButton(1,width/2+10,y,140,20,"Add Track"));buttonList.add(new GuiButton(2,width/2-50,y+28,100,20,"Back"));}
 @Override protected void keyTyped(char c,int k)throws java.io.IOException{if(k==1){mc.displayGuiScreen(parent);return;}if(markerName!=null)markerName.textboxKeyTyped(c,k);if(trackName!=null)trackName.textboxKeyTyped(c,k);super.keyTyped(c,k);}
 @Override protected void mouseClicked(int x,int y,int b)throws java.io.IOException{super.mouseClicked(x,y,b);if(markerName!=null)markerName.mouseClicked(x,y,b);if(trackName!=null)trackName.mouseClicked(x,y,b);}
 @Override protected void actionPerformed(GuiButton b){if(b.id==0){String name=markerName.getText().trim();if(!name.isEmpty()){timeline.addMarker(new TimelineMarker(timeline.duration(),name,TimelineMarkerKind.MANUAL));markerName.setText("");status="Marker added";}else status="Enter a marker name";}else if(b.id==1){String name=trackName.getText().trim();if(!name.isEmpty()){timeline.addTrack(new TimelineTrack("track-"+java.util.UUID.randomUUID().toString(),name));trackName.setText("");status="Track added";}else status="Enter a track name";}else if(b.id==2)mc.displayGuiScreen(parent);}
 @Override public void drawScreen(int mx,int my,float pt){drawDefaultBackground();drawCenteredString(fontRendererObj,"TIMELINE EDITOR",width/2,22,0xFFC83D);int y=42;drawString(fontRendererObj,"Duration: "+timeline.duration()+" ms",width/2-150,y,0xFFFFFF);y+=14;for(TimelineTrack t:timeline.getTracks()){drawString(fontRendererObj,"Track: "+t.getName()+" ("+t.getClips().size()+" clips)",width/2-150,y,0xBBBBBB);y+=12;}for(TimelineMarker m:timeline.getMarkers()){if(y>height/2+32)break;drawString(fontRendererObj,"Marker "+m.getTimeMillis()+" ms: "+m.getLabel(),width/2-150,y,0xFFFFFF);y+=12;}markerName.drawTextBox();trackName.drawTextBox();drawCenteredString(fontRendererObj,status,width/2,height-18,0xBBBBBB);super.drawScreen(mx,my,pt);}
}